'use strict';
const $=s=>document.querySelector(s);
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
let tracks=[],events=[],selected=null,selectedDetail=null,localAudioUrl=null;
const audio=$('#audio');
function releaseAudio(){audio.pause();audio.removeAttribute('src');audio.load();if(localAudioUrl){URL.revokeObjectURL(localAudioUrl);localAudioUrl=null;}$('#audio-file').value='';}
function selectTrack(t){if(selected?.id!==t.id){releaseAudio();selected=t;audio.hidden=!t.audioSrc;$('#audio-status').textContent=t.audioSrc?'登録音源':'音源未登録 · 手元の音源で試せます';if(t.audioSrc)audio.src=t.audioSrc;}$('#playing-title').textContent=t.title;$('#player').hidden=false;document.body.classList.add('has-player');}
function setPanel(panel){if(panel==='lyrics'&&!selectedDetail?.lyricsByOwner)return;$('#notes-panel').hidden=panel!=='notes';$('#lyrics-panel').hidden=panel!=='lyrics';document.querySelectorAll('[data-panel]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.panel===panel)));}
function openDetail(t){selectedDetail=t;$('#event-notes').hidden=true;$('#credits').hidden=false;$('.detail-actions').hidden=false;$('#detail-tabs').hidden=false;$('#lyric-status').hidden=false;$('#detail-kind').textContent='SONG / COMMIT';$('#detail-period').textContent=events.find(e=>e.id===t.historyEventId)?.shortLabel||t.displayPeriod;$('#detail-title').textContent=t.title;$('#credits').textContent='作曲：'+t.composer+(t.lyricist?' ／ 作詞：'+t.lyricist:' ／ 作詞：未確認')+(t.audioVersionYear?' ／ 音源制作：'+t.audioVersionYear:'');$('#notes-then').textContent=t.notesThen||'曲ごとのノーツは、これから。時代の背景は履歴の「時代のノーツ」で読めます。';$('#notes-now').textContent=t.notesNow||'現在の音源や、今聴いて感じることを追記します。';$('#detail-source').hidden=!t.sourceUrl;if(t.sourceUrl)$('#detail-source').href=t.sourceUrl;$('#lyric-status').textContent=t.lyricsByOwner?'':t.lyricCreditStatus==='unconfirmed'?'作詞者を確認してから、歌詞を掲載します。':'作詞：'+t.lyricist+'。歌詞は掲載しません。';$('[data-panel="lyrics"]').hidden=!t.lyricsByOwner||!t.lyrics;$('#lyrics').textContent=t.lyricsByOwner?(t.lyrics||''):'';setPanel('notes');$('#detail').showModal();}
$('#detail-play').addEventListener('click',()=>{selectTrack(selectedDetail);$('#detail').close();$('#audio-file').focus();});
$('#close-detail').addEventListener('click',()=>$('#detail').close());
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=$('#detail').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#detail').close();}});
document.querySelectorAll('[data-panel]').forEach(b=>b.addEventListener('click',()=>setPanel(b.dataset.panel)));
$('#close-player').addEventListener('click',()=>{releaseAudio();selected=null;$('#player').hidden=true;document.body.classList.remove('has-player');});
$('#audio-file').addEventListener('change',e=>{const f=e.target.files?.[0];if(!f)return;if(!f.type.startsWith('audio/')){$('#audio-status').textContent='音声ファイルを選んでください';return;}audio.pause();if(localAudioUrl)URL.revokeObjectURL(localAudioUrl);localAudioUrl=URL.createObjectURL(f);audio.src=localAudioUrl;audio.hidden=false;$('#audio-status').textContent='端末内の試聴：'+f.name;});
audio.addEventListener('error',()=>{$('#audio-status').textContent='この音源を再生できません。別の形式をお試しください。';});
window.addEventListener('pagehide',()=>{if(localAudioUrl)URL.revokeObjectURL(localAudioUrl);});
const branchFor=e=>e.id==='felice'?'felice':e.id==='patalp'?'patalp':'main';
let renderedRows=[];
function eventRow(e){const branch=branchFor(e);return {kind:'event',key:e.id,branch,event:e};}
function songRows(e){return(e.trackIds||[]).map(id=>tracks.find(t=>t.id===id)).filter(Boolean).map(track=>({kind:'song',key:'song-'+track.id,branch:branchFor(e),track,event:e}));}
function makeRows(){const rows=[];for(const e of events){if(e.id==='patalp')continue;if(e.id==='felice'){const p=events.find(x=>x.id==='patalp');rows.push(eventRow(e));if(p)rows.push(eventRow(p));const fSongs=songRows(e),pSongs=p?songRows(p):[];for(let i=0;i<Math.max(fSongs.length,pSongs.length);i++){if(fSongs[i])rows.push(fSongs[i]);if(pSongs[i])rows.push(pSongs[i]);}}else rows.push(eventRow(e),...songRows(e));}return rows;}
function render(){const list=$('#history-list');list.replaceChildren();renderedRows=makeRows();for(const row of renderedRows){const li=el('li',undefined,'log-row '+row.kind+'-row '+row.branch);li.dataset.key=row.key;li.dataset.branch=row.branch;if(row.kind==='song'){const b=el('button',undefined,'song-commit');b.setAttribute('aria-label',row.track.title+'の音源・歌詞・ライナーノーツを開く');b.append(el('span',row.track.title,'commit-title'));if(row.track.creatorCreditTags?.length){const tags=el('span',undefined,'credit-tags');for(const value of row.track.creatorCreditTags)tags.append(el('span',value,'credit-tag'));b.append(tags);}b.addEventListener('click',()=>openDetail(row.track));li.append(b);}else{const e=row.event;const label=el('div',undefined,'event-line');const value=e.displayYear||e.year;const year=value?String(value):'—';label.append(el('span',year,'log-year'),el('span',e.shortLabel||e.title,'event-label'));li.append(label);}list.append(li);}requestAnimationFrame(drawGraph);}
function drawGraph(){const svg=$('#graph');svg.replaceChildren();if(!renderedRows.length)return;const height=$('#tree').offsetHeight;const width=svg.getBoundingClientRect().width;svg.setAttribute('viewBox',`0 0 ${width} ${height}`);const x={main:width*.17,felice:width*.50,patalp:width*.83};const domRows=[...$('#history-list').children];const coords=renderedRows.map((row,i)=>({...row,y:domRows[i].offsetTop+(26)}));const colors={main:'#6d8173',felice:'#976522',patalp:'#506ca5'};const ns='http://www.w3.org/2000/svg';const path=(d,color)=>{const p=document.createElementNS(ns,'path');p.setAttribute('d',d);p.setAttribute('stroke',color);p.setAttribute('stroke-width','1.8');p.setAttribute('fill','none');svg.append(p);};const mainRows=coords.filter(r=>r.branch==='main');path(`M ${x.main} ${mainRows[0].y} L ${x.main} ${mainRows.at(-1).y}`,colors.main);const firstBranch=coords.findIndex(r=>r.branch!=='main');const origin=coords.slice(0,firstBranch).filter(r=>r.branch==='main').at(-1);for(const branch of ['felice','patalp']){const branchRows=coords.filter(r=>r.branch===branch);if(!origin||!branchRows.length)continue;const first=branchRows[0].y,last=branchRows.at(-1).y;const bend=Math.min(30,(first-origin.y)/2);path(`M ${x.main} ${origin.y} C ${x.main} ${origin.y+bend}, ${x[branch]} ${origin.y+bend}, ${x[branch]} ${first} L ${x[branch]} ${last}`,colors[branch]);}for(const row of coords){const circle=document.createElementNS(ns,'circle');circle.setAttribute('cx',String(x[row.branch]));circle.setAttribute('cy',String(row.y));circle.setAttribute('r',row.kind==='song'?'5.5':'3');circle.setAttribute('fill',row.kind==='song'?colors[row.branch]:'#fafaf7');circle.setAttribute('stroke',colors[row.branch]);circle.setAttribute('stroke-width','1.8');svg.append(circle);if(row.kind==='song'){const hit=document.createElementNS(ns,'circle');hit.setAttribute('cx',String(x[row.branch]));hit.setAttribute('cy',String(row.y));hit.setAttribute('r','12');hit.setAttribute('fill','transparent');hit.style.pointerEvents='all';hit.style.cursor='pointer';hit.addEventListener('click',()=>openDetail(row.track));svg.append(hit);}}}
const observer=new ResizeObserver(()=>requestAnimationFrame(drawGraph));observer.observe($('#tree'));window.addEventListener('resize',()=>requestAnimationFrame(drawGraph));
async function init(){try{const responses=await Promise.all([fetch('tracks.json'),fetch('history.json')]);if(responses.some(r=>!r.ok))throw Error('data');[tracks,events]=await Promise.all(responses.map(r=>r.json()));render();}catch{$('#error').hidden=false;$('#error').textContent='履歴を読み込めませんでした。ページを再読み込みしてください。';}}
init();
